let language="en";
const toggle=document.getElementById("languageToggle");
function setLanguage(next){language=next;document.documentElement.lang=next;document.querySelectorAll("[data-i18n]").forEach(el=>{const value=copy[next][el.dataset.i18n];if(value!==undefined)el.innerHTML=value});toggle.setAttribute("aria-label",next==="en"?"Cambiar idioma a español":"Switch language to English");toggle.querySelectorAll("span").forEach((el,i)=>el.style.opacity=(next==="en"&&i===0)||(next==="es"&&i===1)?"1":".45")}
toggle.addEventListener("click",()=>setLanguage(language==="en"?"es":"en"));
const menu=document.getElementById("menuToggle"),panel=document.getElementById("mobilePanel");
menu.addEventListener("click",()=>{const open=panel.classList.toggle("open");menu.setAttribute("aria-expanded",String(open));panel.setAttribute("aria-hidden",String(!open))});
panel.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{panel.classList.remove("open");menu.setAttribute("aria-expanded","false")}));
document.getElementById("year").textContent=new Date().getFullYear();setLanguage("en");
